'use client';
import NextLink from 'next/link';
import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ComponentProps,
  type ReactNode,
} from 'react';

type Check = () => boolean;
function createGuard() {
  const checks = new Set<Check>();
  return {
    register(check: Check) {
      checks.add(check);
      return () => {
        checks.delete(check);
      };
    },
    pending: () => [...checks].some((check) => check()),
  };
}
const Context = createContext<ReturnType<typeof createGuard> | null>(null);
export function WorkspaceNavigation({ children }: { children: ReactNode }) {
  const [guard] = useState(createGuard);
  useEffect(() => {
    function warn(event: BeforeUnloadEvent) {
      if (!guard.pending()) return;
      event.preventDefault();
      event.returnValue = '';
    }
    window.addEventListener('beforeunload', warn);
    return () => window.removeEventListener('beforeunload', warn);
  }, [guard]);
  return <Context value={guard}>{children}</Context>;
}
export function useWorkspaceNavigation() {
  const guard = useContext(Context);
  if (!guard) throw new Error('WorkspaceNavigation provider is required.');
  return guard;
}
/** Check live save receipts, including hidden workspaces, without collecting their contents. */
export default function GuardedLink({ onNavigate, ...props }: ComponentProps<typeof NextLink>) {
  const guard = useWorkspaceNavigation();
  return (
    <NextLink
      {...props}
      onNavigate={(event) => {
        onNavigate?.(event);
        if (
          guard.pending() &&
          !window.confirm(
            'יש עבודה שעדיין לא התקבל אישור לשמירתה. מעבר לעמוד אחר עלול לגרום לאובדן שינויים. לעבור בכל זאת?',
          )
        )
          event.preventDefault();
      }}
    />
  );
}

'use client';
import { useEffect, useRef, useState } from 'react';
import { z } from 'zod';
import { useWorkspaceNavigation } from '@/components/workspace-navigation';
import {
  DraftSaveCoordinator,
  DraftSaveError,
  type SaveView,
} from '@/lib/templates/save-coordinator';
import {
  validateTemplateDocument,
  type TemplateDefinition,
  type TemplateDocument,
} from '@/lib/templates/schema';
import {
  exportTemplateCSV,
  exportTemplateJSON,
  importTemplateCSV,
  importTemplateJSON,
  templateMarkdown,
  templateSubmission,
} from '@/lib/templates/formats';
import { TableEditor } from './table-editor';
import { MarkdownEditor, MarkdownPreview } from './markdown-editor';
import styles from './workspace.module.css';
export type InitialWorkspace = {
  definition: TemplateDefinition;
  definitionHash: string;
  document: TemplateDocument;
  revision: number;
  readOnly: boolean;
};
function download(name: string, text: string, type: string) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = name;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function TemplateWorkspace({
  initial,
  curriculumVersion,
  disabled,
  onUse,
  onSubmissionState,
}: {
  initial: InitialWorkspace;
  curriculumVersion: string;
  disabled: boolean;
  onUse: (text: string) => void;
  onSubmissionState: (id: string, state: { revision: number; ready: boolean }) => void;
}) {
  const navigation = useWorkspaceNavigation();
  const [coordinator] = useState(
    () =>
      new DraftSaveCoordinator({
        ...initial,
        curriculumVersion,
        uuid: () => crypto.randomUUID(),
        send: async (input) => {
          const response = await fetch('/api/templates/drafts', {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(input),
            signal: AbortSignal.timeout(20000),
          });
          const body = await response.json();
          if (!response.ok)
            throw new DraftSaveError(typeof body.error === 'string' ? body.error : 'SAVE_FAILED');
          return body;
        },
      }),
  );
  const [view, setView] = useState<SaveView>(() => coordinator.view());
  const [local, setLocal] = useState(initial.document);
  const [exportingPDF, setExportingPDF] = useState(false);
  const [invalid, setInvalid] = useState(false),
    [message, setMessage] = useState('');
  const invalidRef = useRef(false);
  const locked = disabled || initial.readOnly || view.status === 'read-only';
  useEffect(() => coordinator.subscribe(() => setView(coordinator.view())), [coordinator]);
  useEffect(() => {
    if (locked || invalid || view.status !== 'unsaved') return;
    const timer = setTimeout(() => {
      void coordinator.flush().catch(() => {});
    }, 700);
    return () => clearTimeout(timer);
  }, [coordinator, invalid, locked, view]);
  useEffect(
    () =>
      navigation.register(
        () => invalidRef.current || !['saved', 'read-only'].includes(coordinator.view().status),
      ),
    [coordinator, navigation],
  );

  function edit(document: TemplateDocument) {
    onSubmissionState(initial.definition.id, { revision: view.revision, ready: false });
    setLocal(document);
    setMessage('');
    try {
      coordinator.edit(document);
      invalidRef.current = false;
      setInvalid(false);
    } catch {
      invalidRef.current = true;
      setInvalid(true);
    }
  }
  let text = '',
    ready = false;
  try {
    text = templateMarkdown(local, initial.definition);
    templateSubmission(local, initial.definition);
    ready = true;
  } catch {
    /* Incomplete/temporarily invalid work remains editable and is never submitted. */
  }
  useEffect(() => {
    onSubmissionState(initial.definition.id, {
      revision: view.revision,
      ready: ready && !invalid && view.status === 'saved' && !initial.readOnly,
    });
  }, [
    onSubmissionState,
    initial.definition.id,
    initial.readOnly,
    view.revision,
    view.status,
    ready,
    invalid,
  ]);
  async function reloadSaved() {
    if (
      !window.confirm('טעינת הטיוטה השמורה תחליף את העבודה המקומית. הורד עותק לפני ההחלפה. להמשיך?')
    )
      return;
    try {
      const response = await fetch(
        `/api/templates/drafts?${new URLSearchParams({ templateId: initial.definition.id, definitionHash: initial.definitionHash })}`,
        { cache: 'no-store' },
      );
      if (!response.ok) throw new Error('LOAD_FAILED');
      const result = z
        .object({
          draft: z.object({
            definitionHash: z.literal(initial.definitionHash),
            revision: z.number().int().nonnegative(),
            readOnly: z.boolean(),
            document: z.unknown(),
          }),
        })
        .parse(await response.json());
      const document = validateTemplateDocument(result.draft.document, initial.definition);
      coordinator.replaceFromServer(document, result.draft.revision, result.draft.readOnly);
      setLocal(document);
      invalidRef.current = false;
      setInvalid(false);
      setMessage('הטיוטה השמורה נטענה.');
    } catch {
      setMessage('הטעינה נכשלה. העבודה המקומית לא הוחלפה.');
    }
  }
  const statuses = {
    saved: 'הטיוטה שמורה בחשבון שלך.',
    unsaved: 'יש שינויים שטרם נשמרו.',
    saving: 'שומר את הטיוטה…',
    failed: 'לא התקבל אישור לשמירת השינויים. העבודה עדיין מוצגת כאן; נסה שוב או הורד עותק.',
    conflict:
      'גרסת הטיוטה או התבנית השתנתה. העבודה המקומית עדיין מוצגת כאן; הורד עותק לפני טעינת הטיוטה השמורה.',
    'read-only': 'הטיוטה הזו זמינה לקריאה בלבד.',
  };
  return (
    <div className={styles.workspace} data-template-workspace={initial.definition.id}>
      <p className="muted">{initial.definition.guidance}</p>
      <p role="status" aria-live="polite">
        {invalid
          ? 'הטיוטה לא נשמרת כרגע. אם זו טבלה, ודא שלכל עמודה יש שם. בדוק גם שהתוכן אינו חורג מהמגבלות.'
          : statuses[view.status]}
      </p>
      <TableEditor
        definition={initial.definition}
        document={local}
        onChange={edit}
        disabled={locked}
      />
      <MarkdownEditor
        id={`${initial.definition.id}-notes`}
        value={local.notes}
        onChange={(notes) => edit({ ...local, notes })}
        disabled={locked}
      />
      <details>
        <summary>תצוגה מקדימה של העבודה</summary>
        <MarkdownPreview text={text || local.notes} />
      </details>
      <div className="template-toolbar">
        {invalid && (
          <button
            type="button"
            className="button secondary"
            onClick={() =>
              download(
                `${initial.definition.id}-local-copy.json`,
                JSON.stringify(local, null, 2),
                'application/json',
              )
            }
          >
            הורדת עותק מקומי לתיקון
          </button>
        )}
        {invalid && (
          <p className="muted">
            העותק כולל את העבודה כפי שהיא כעת. ייתכן שיהיה צורך לתקן אותו לפני ייבוא מחדש.
          </p>
        )}

        <button
          type="button"
          className="button secondary"
          disabled={locked || invalid || view.status !== 'failed'}
          onClick={() => {
            void coordinator.flush(true).catch(() => {});
          }}
        >
          ניסיון שמירה נוסף
        </button>
        <button
          type="button"
          className="button secondary"
          disabled={view.status !== 'conflict'}
          onClick={() => {
            void reloadSaved();
          }}
        >
          טעינת הטיוטה השמורה
        </button>
        <button
          type="button"
          className="button secondary"
          disabled={invalid}
          onClick={() =>
            download(
              `${initial.definition.id}.json`,
              exportTemplateJSON(local, initial.definition),
              'application/json',
            )
          }
        >
          הורדת JSON
        </button>
        <button
          type="button"
          className="button secondary"
          disabled={invalid || exportingPDF}
          onClick={async () => {
            setExportingPDF(true);
            try {
              const { exportTemplatePDF } = await import('@/lib/templates/pdf');
              const blob = await exportTemplatePDF(local, initial.definition);
              const url = URL.createObjectURL(blob);
              const anchor = document.createElement('a');
              anchor.href = url;
              anchor.download = `${initial.definition.id}.pdf`;
              anchor.click();
              setTimeout(() => URL.revokeObjectURL(url), 1000);
            } catch {
              setMessage('לא הצלחנו ליצור את קובץ ה־PDF. העבודה עדיין כאן; אפשר לנסות שוב.');
            } finally {
              setExportingPDF(false);
            }
          }}
        >
          {exportingPDF ? 'מכין PDF…' : 'הורדת PDF'}
        </button>
        {local.table && (
          <button
            type="button"
            className="button secondary"
            disabled={invalid}
            onClick={() =>
              download(
                `${initial.definition.id}.csv`,
                exportTemplateCSV(local, initial.definition),
                'text/csv;charset=utf-8',
              )
            }
          >
            הורדת CSV
          </button>
        )}
        <label className="field-label">
          ייבוא עבודה מ־JSON{local.table ? ' או CSV' : ''}
          <input
            type="file"
            accept={local.table ? '.json,.csv' : '.json'}
            disabled={locked}
            onChange={async (event) => {
              const file = event.target.files?.[0];
              event.target.value = '';
              if (!file) return;
              if (file.size > 180000) {
                setMessage('הקובץ גדול מדי. אפשר לייבא עד 180KB.');
                return;
              }
              try {
                const source = await file.text();
                const next = file.name.toLowerCase().endsWith('.csv')
                  ? importTemplateCSV(source, local, initial.definition)
                  : importTemplateJSON(source, initial.definition);
                if (window.confirm('הייבוא יחליף את העבודה המקומית. להמשיך?')) edit(next);
              } catch {
                setMessage('הייבוא נכשל. בדוק שהקובץ מתאים לתבנית. העבודה הקיימת לא הוחלפה.');
              }
            }}
          />
        </label>
        <button
          type="button"
          className="button primary"
          disabled={locked || invalid || !ready || view.status !== 'saved'}
          onClick={() => {
            if (!window.confirm('תוכן התבנית יחליף את התשובה הקיימת בסעיף הזה. להמשיך?')) return;
            onUse(templateSubmission(local, initial.definition).text);
            setMessage(
              'תוכן התבנית החליף את התשובה בסעיף הזה. בדוק את כל הסעיפים לפני הגשת העבודה.',
            );
          }}
        >
          החלפת התשובה בתוכן התבנית
        </button>
      </div>
      <p role="status">{message}</p>
    </div>
  );
}

'use client';
import {
  MAX_COLUMNS,
  MAX_ROWS,
  type TemplateDefinition,
  type TemplateDocument,
} from '@/lib/templates/schema';

/** Required starter columns keep their stable IDs; optional columns remain removable. */
export function TableEditor({
  definition,
  document,
  onChange,
  disabled = false,
}: {
  definition: TemplateDefinition;
  document: TemplateDocument;
  onChange: (document: TemplateDocument) => void;
  disabled?: boolean;
}) {
  const table = document.table;
  if (definition.kind !== 'table' || !table) return null;
  const required = new Set(definition.starter.columns.map((column) => column.id));
  const change = (next: NonNullable<TemplateDocument['table']>) =>
    onChange({ ...document, table: next });
  return (
    <div className="template-table-editor">
      <p className="muted" id={`${definition.id}-table-help`}>
        מלא את התאים. אפשר לערוך את שמות העמודות ולהוסיף שורות ועמודות לפי הצורך.
      </p>
      <div
        className="template-table-scroll"
        role="region"
        tabIndex={0}
        aria-label="טבלת העבודה — אפשר לגלול לרוחב"
        aria-describedby={`${definition.id}-table-help`}
      >
        <table>
          <caption>טבלת העבודה שלך</caption>
          <thead>
            <tr>
              {table.columns.map((column, columnIndex) => (
                <th scope="col" key={column.id}>
                  <label htmlFor={`${definition.id}-column-${column.id}`}>
                    שם עמודה {columnIndex + 1}
                  </label>
                  <input
                    id={`${definition.id}-column-${column.id}`}
                    value={column.label}
                    maxLength={80}
                    disabled={disabled}
                    dir="auto"
                    onChange={(event) =>
                      change({
                        ...table,
                        columns: table.columns.map((item, i) =>
                          i === columnIndex ? { ...item, label: event.target.value } : item,
                        ),
                      })
                    }
                  />
                  {!required.has(column.id) && (
                    <button
                      type="button"
                      disabled={disabled}
                      aria-label={`הסרת עמודה ${column.label || columnIndex + 1}`}
                      onClick={() =>
                        change({
                          columns: table.columns.filter((_, i) => i !== columnIndex),
                          rows: table.rows.map((row) => row.filter((_, i) => i !== columnIndex)),
                        })
                      }
                    >
                      הסרת עמודה
                    </button>
                  )}
                </th>
              ))}
              <th scope="col">פעולות בשורה</th>
            </tr>
          </thead>
          <tbody>
            {table.rows.map((row, rowIndex) => (
              <tr key={rowIndex}>
                {row.map((value, columnIndex) => (
                  <td key={table.columns[columnIndex].id}>
                    <textarea
                      value={value}
                      maxLength={4000}
                      rows={3}
                      disabled={disabled}
                      dir="auto"
                      aria-label={`שורה ${rowIndex + 1}, ${table.columns[columnIndex].label || `עמודה ${columnIndex + 1}`}`}
                      onChange={(event) =>
                        change({
                          ...table,
                          rows: table.rows.map((item, i) =>
                            i === rowIndex
                              ? item.map((cell, j) =>
                                  j === columnIndex ? event.target.value : cell,
                                )
                              : item,
                          ),
                        })
                      }
                    />
                  </td>
                ))}
                <td>
                  <button
                    type="button"
                    disabled={disabled}
                    aria-label={`הסרת שורה ${rowIndex + 1}`}
                    onClick={() =>
                      change({ ...table, rows: table.rows.filter((_, i) => i !== rowIndex) })
                    }
                  >
                    הסרת שורה
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="template-toolbar" aria-label="עריכת מבנה הטבלה">
        <button
          type="button"
          className="button secondary"
          disabled={disabled || table.rows.length >= MAX_ROWS}
          onClick={() => change({ ...table, rows: [...table.rows, table.columns.map(() => '')] })}
        >
          הוספת שורה
        </button>
        <button
          type="button"
          className="button secondary"
          disabled={disabled || table.columns.length >= MAX_COLUMNS}
          onClick={() => {
            const id = `CUSTOM_${crypto.randomUUID().replaceAll('-', '').toUpperCase()}`;
            change({
              columns: [...table.columns, { id, label: `עמודה ${table.columns.length + 1}` }],
              rows: table.rows.map((row) => [...row, '']),
            });
          }}
        >
          הוספת עמודה
        </button>
        <span className="muted">
          {table.rows.length} מתוך {MAX_ROWS} שורות · {table.columns.length} מתוך {MAX_COLUMNS}{' '}
          עמודות
        </span>
      </div>
    </div>
  );
}

'use client';
import { useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { codeTokens, formatMarkdown, type MarkdownFormat } from '@/lib/templates/markdown-edit';

export function MarkdownPreview({ text }: { text: string }) {
  return (
    <div className="template-preview" dir="auto">
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        skipHtml
        components={{
          table: ({ children }) => (
            <div
              className="template-table-scroll"
              role="region"
              tabIndex={0}
              aria-label="תצוגת הטבלה — אפשר לגלול לרוחב"
            >
              <table>{children}</table>
            </div>
          ),
          // Links remain readable text here: preview never navigates away from unsaved work.
          a: ({ children }) => <span className="text-link">{children}</span>,
          img: ({ alt }) => <span>{alt || 'תמונה'}</span>,
          code: ({ children, className }) => (
            <code className={className}>
              {codeTokens(String(children)).map((token, i) => (
                <span key={i} className={`code-token-${token.kind}`}>
                  {token.text}
                </span>
              ))}
            </code>
          ),
        }}
      >
        {text}
      </ReactMarkdown>
    </div>
  );
}
export function MarkdownEditor({
  id,
  value,
  onChange,
  disabled = false,
}: {
  id: string;
  value: string;
  onChange: (value: string) => void;
  disabled?: boolean;
}) {
  const editor = useRef<HTMLTextAreaElement>(null);
  const formats: [MarkdownFormat, string][] = [
    ['bold', 'הדגשה'],
    ['italic', 'כתב נטוי'],
    ['heading', 'כותרת'],
    ['list', 'רשימה'],
    ['code', 'קטע קוד'],
  ];
  return (
    <div className="template-markdown-editor">
      <label htmlFor={id}>הסבר, תוצאות ומה למדתי</label>
      <div className="template-toolbar" role="group" aria-label="עיצוב הטקסט">
        {formats.map(([format, label]) => (
          <button
            type="button"
            key={format}
            onClick={() => {
              const element = editor.current;
              if (!element) return;
              const change = formatMarkdown(
                value,
                element.selectionStart,
                element.selectionEnd,
                format,
              );
              onChange(change.text);
              requestAnimationFrame(() => {
                element.focus();
                element.setSelectionRange(change.start, change.end);
              });
            }}
            disabled={disabled || value.length > 11980}
          >
            {label}
          </button>
        ))}
      </div>
      <textarea
        id={id}
        ref={editor}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        maxLength={12000}
        rows={8}
        disabled={disabled}
        dir="auto"
      />
      <span className="muted">{value.length.toLocaleString('he-IL')} מתוך 12,000 תווים</span>
    </div>
  );
}

import { Fragment } from 'react';
import { Document, Font, Page, View, pdf } from '@react-pdf/renderer';
import { TemplateText as Text } from './pdf-text';
import { PDFMarkdown } from './pdf-markdown';
import { validateTemplateDocument, type TemplateDefinition } from './schema';

Font.register({
  family: 'TemplateHebrew',
  fonts: [
    { src: '/fonts/template-pdf/hebrew.woff' },
    { src: '/fonts/template-pdf/hebrew-bold.woff', fontWeight: 700 },
  ],
});
Font.register({
  family: 'TemplateLatin',
  fonts: [
    { src: '/fonts/template-pdf/latin.woff' },
    { src: '/fonts/template-pdf/latin-bold.woff', fontWeight: 700 },
  ],
});
Font.registerHyphenationCallback((word) => [word]);
const textStyle = {
  fontFamily: ['TemplateHebrew', 'TemplateLatin'],
  fontSize: 11,
  lineHeight: 1.5,
  direction: 'rtl' as const,
  textAlign: 'right' as const,
};

/** Local-only export of the validated buffer; no persistence or assessment claim. */
export async function exportTemplatePDF(raw: unknown, definition: TemplateDefinition) {
  const document = validateTemplateDocument(raw, definition);
  return pdf(
    <Document title={`עבודה — ${definition.lessonId}`} language="he">
      <Page
        size="A4"
        style={{ padding: 36, ...textStyle }}
        layout={({ children, pageNumber, totalPages }) => (
          <>
            <View style={{ flexGrow: 1 }}>{children}</View>
            <Text
              style={{
                height: 14,
                marginTop: 12,
                lineHeight: 1,
                fontFamily: 'Helvetica',
                fontSize: 9,
                textAlign: 'center',
                direction: 'ltr',
              }}
            >
              {`${pageNumber ?? ''} / ${totalPages ?? ''}`}
            </Text>
          </>
        )}
      >
        <Text style={{ fontSize: 18, marginBottom: 12 }}>העבודה שלי</Text>
        <Text style={{ direction: 'ltr', textAlign: 'left', marginBottom: 12 }}>
          {definition.id}
        </Text>
        <Text style={{ marginBottom: 16 }}>{definition.prompt}</Text>
        {document.table?.rows.map((row, index) => (
          <View
            key={index}
            style={{ marginBottom: 14, padding: 8, borderWidth: 1, borderColor: '#777777' }}
          >
            <Text style={{ marginBottom: 6 }}>שורה {index + 1}</Text>
            {row.map((value, column) => (
              <Fragment key={column}>
                <Text style={{ color: '#33554a' }}>{document.table!.columns[column].label}</Text>
                <Text style={{ marginBottom: 6 }}>{value || '—'}</Text>
              </Fragment>
            ))}
          </View>
        ))}
        <Text style={{ fontSize: 14, marginBottom: 8 }}>הסבר, תוצאות ומה למדתי</Text>
        <PDFMarkdown text={document.notes} />
      </Page>
    </Document>,
  ).toBlob();
}

import { Fragment, type ReactNode } from 'react';
import { View } from '@react-pdf/renderer';
import { TemplateText as Text } from './pdf-text';
import { unified } from 'unified';
import remarkParse from 'remark-parse';
import remarkGfm from 'remark-gfm';
import type { Root, RootContent, PhrasingContent, ListItem, TableRow, TableCell } from 'mdast';

type Node = Root | RootContent | PhrasingContent | ListItem | TableRow | TableCell;
const children = (node: Node): ReactNode[] =>
  'children' in node
    ? node.children.map((child, i) => <Fragment key={i}>{render(child)}</Fragment>)
    : [];

/** Same inert content policy as the editor: no raw HTML, fetched images or active links. */
function render(node: Node): ReactNode {
  switch (node.type) {
    case 'root':
      return children(node);
    case 'text':
      return node.value;
    case 'paragraph':
      return <Text style={{ marginBottom: 8 }}>{children(node)}</Text>;
    case 'heading':
      return (
        <Text style={{ fontWeight: 700, fontSize: Math.max(12, 20 - node.depth), marginBottom: 8 }}>
          {children(node)}
        </Text>
      );
    case 'strong':
      return <Text style={{ fontWeight: 700 }}>{children(node)}</Text>;
    case 'emphasis':
      return <Text style={{ textDecoration: 'underline' }}>{children(node)}</Text>;
    case 'delete':
      return <Text style={{ textDecoration: 'line-through' }}>{children(node)}</Text>;
    case 'inlineCode':
      return <Text style={{ direction: 'ltr', backgroundColor: '#eeeeee' }}>{node.value}</Text>;
    case 'code':
      return (
        <Text
          style={{
            direction: 'ltr',
            textAlign: 'left',
            fontSize: 10,
            marginBottom: 10,
            padding: 8,
            backgroundColor: '#eeeeee',
          }}
        >
          {node.value}
        </Text>
      );
    case 'break':
      return '\n';
    case 'link':
    case 'linkReference':
      return children(node);
    case 'image':
    case 'imageReference':
      return node.alt || 'תמונה';
    case 'list':
      return (
        <View style={{ marginBottom: 8 }}>
          {node.children.map((item, index) => {
            const marker = `${node.ordered ? `${(node.start ?? 1) + index}.` : '•'}${item.checked === null || item.checked === undefined ? '' : item.checked ? ' [x]' : ' [ ]'} `;
            const [first, ...rest] = item.children;
            return (
              <View key={index} style={{ paddingRight: 12 }}>
                {first?.type === 'paragraph' ? (
                  <Text style={{ marginBottom: 8 }}>
                    {marker}
                    {children(first)}
                  </Text>
                ) : (
                  <>
                    {<Text>{marker}</Text>}
                    {first && render(first)}
                  </>
                )}
                {rest.map((child, i) => (
                  <Fragment key={i}>{render(child)}</Fragment>
                ))}
              </View>
            );
          })}
        </View>
      );
    case 'blockquote':
      return (
        <View
          style={{ borderRightWidth: 2, borderColor: '#777777', paddingRight: 10, marginBottom: 8 }}
        >
          {children(node)}
        </View>
      );
    case 'table':
      return (
        <View>
          {node.children.map((row, index) => (
            <View
              key={index}
              style={{ borderBottomWidth: 1, borderColor: '#777777', marginBottom: 8 }}
            >
              {row.children.map((cell, column) => (
                <Text key={column} style={{ marginBottom: 4 }}>
                  {index > 0 && (
                    <Text style={{ fontWeight: 700 }}>
                      {children(node.children[0].children[column])}
                      {': '}
                    </Text>
                  )}
                  {children(cell)}
                </Text>
              ))}
            </View>
          ))}
        </View>
      );
    case 'thematicBreak':
      return <View style={{ borderBottomWidth: 1, borderColor: '#777777', marginBottom: 10 }} />;
    case 'html':
    case 'definition':
      return null;
    default:
      return 'children' in node ? children(node) : null;
  }
}
export function PDFMarkdown({ text }: { text: string }) {
  const tree = unified().use(remarkParse).use(remarkGfm).parse(text);
  return <View>{render(tree)}</View>;
}

import type { PropsWithChildren } from 'react';
import { Text as PDFText, type TextProps } from '@react-pdf/renderer';

/** Renderer direction is not inherited. Set it on each text node, preserving explicit LTR code. */
export function TemplateText({ style, ...props }: PropsWithChildren<TextProps>) {
  const styles = Array.isArray(style) ? style : [style ?? {}];
  return <PDFText {...props} style={[{ direction: 'rtl' }, ...styles]} />;
}

import { z } from 'zod';
import { definitionHashSchema } from './persistence';
