export type DraftSaveInput = z.infer<typeof draftSaveSchema>;

import { z } from 'zod';
import type { Assessment } from '../curriculum/assessment';

const id = z.string().regex(/^[A-Z][A-Z0-9_]{0,199}$/);
const version = z.string().regex(/^\d{1,4}\.\d{1,4}\.\d{1,4}$/);
export const MAX_DOCUMENT_BYTES = 180_000;
export const MAX_ROWS = 100;
export const MAX_COLUMNS = 12;
const cell = z
  .string()
  .max(4000)
  .refine((value) => !/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(value));
export const columnSchema = z.strictObject({
  id,
  label: z.string().trim().min(1).max(80),
});
const tableSchema = z
  .strictObject({
    columns: z.array(columnSchema).min(1).max(MAX_COLUMNS),
    rows: z.array(z.array(cell).min(1).max(MAX_COLUMNS)).max(MAX_ROWS),
  })
  .superRefine((table, context) => {
    if (new Set(table.columns.map((column) => column.id)).size !== table.columns.length)
      context.addIssue({ code: 'custom', message: 'DUPLICATE_COLUMN' });
    if (table.rows.some((row) => row.length !== table.columns.length))
      context.addIssue({ code: 'custom', message: 'INVALID_ROW_WIDTH' });
  });

const shared = {
  id,
  version,
  lessonId: id,
  assessmentId: id,
  rubricVersion: version,
  criterionId: id,
  prompt: z.string().min(20).max(4000),
  evidenceHint: z.string().min(10).max(4000),
  guidance: z.string().min(20).max(2000),
};
export const templateDefinitionSchema = z.discriminatedUnion('kind', [
  z.strictObject({ ...shared, kind: z.literal('markdown') }),
  z
    .strictObject({
      ...shared,
      kind: z.literal('table'),
      starter: tableSchema,
      minimumRows: z.number().int().min(1).max(MAX_ROWS),
    })
    .superRefine((definition, context) => {
      if (definition.starter.rows.length < definition.minimumRows)
        context.addIssue({ code: 'custom', message: 'INSUFFICIENT_STARTER_ROWS' });
    }),
]);
export const templateCatalogSchema = z.strictObject({
  schemaVersion: z.literal(1),
  version,
  sourceCurriculumVersion: version,
  templates: z.array(templateDefinitionSchema).min(1).max(2000),
});
export type TemplateDefinition = z.infer<typeof templateDefinitionSchema>;
export type TemplateCatalog = z.infer<typeof templateCatalogSchema>;
export const templateDocumentSchema = z
  .strictObject({
    schemaVersion: z.literal(1),
    templateId: id,
    templateVersion: version,
    notes: z
      .string()
      .max(12000)
      .refine((value) => !/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/.test(value)),
    table: tableSchema.optional(),
  })
  .superRefine((document, context) => {
    if (new TextEncoder().encode(JSON.stringify(document)).byteLength > MAX_DOCUMENT_BYTES)
      context.addIssue({ code: 'custom', message: 'DOCUMENT_TOO_LARGE' });
  });
export type TemplateDocument = z.infer<typeof templateDocumentSchema>;

/** Empty cells are deliberate scaffolding; they never claim a completed learner task. */
export function starterDocument(definition: TemplateDefinition): TemplateDocument {
  return {
    schemaVersion: 1,
    templateId: definition.id,
    templateVersion: definition.version,
    notes: '',
    ...(definition.kind === 'table' ? { table: structuredClone(definition.starter) } : {}),
  };
}
export function validateTemplateDocument(raw: unknown, definition: TemplateDefinition) {
  const document = templateDocumentSchema.parse(raw);
  if (document.templateId !== definition.id || document.templateVersion !== definition.version)
    throw new Error('STALE_TEMPLATE');
  if (definition.kind === 'markdown' && document.table) throw new Error('UNEXPECTED_TABLE');
  if (definition.kind === 'table') {
    if (!document.table) throw new Error('TABLE_REQUIRED');
    const columns = new Set(document.table.columns.map((column) => column.id));
    if (definition.starter.columns.some((column) => !columns.has(column.id)))
      throw new Error('REQUIRED_COLUMN_MISSING');
  }
  return document;
}

/** Exact criterion binding makes a later rubric change visible instead of silently remapping work. */
export function validateTemplateCatalog(
  raw: unknown,
  catalog: { version: string; assessments: Assessment[] },
): TemplateCatalog {
  const bank = templateCatalogSchema.parse(raw);
  if (bank.sourceCurriculumVersion !== catalog.version) throw new Error('TEMPLATE_COURSE_DRIFT');
  const definitions = new Map<string, TemplateDefinition>();
  const ids = new Set<string>();
  for (const definition of bank.templates) {
    const key = `${definition.assessmentId}:${definition.criterionId}`;
    if (ids.has(definition.id) || definitions.has(key)) throw new Error('DUPLICATE_TEMPLATE');
    if (definition.version !== bank.version) throw new Error('TEMPLATE_VERSION_DRIFT');
    ids.add(definition.id);
    definitions.set(key, definition);
  }
  let count = 0;
  for (const assessment of catalog.assessments) {
    for (const criterion of assessment.criteria) {
      count++;
      const definition = definitions.get(`${assessment.id}:${criterion.id}`);
      if (
        !definition ||
        definition.id !== `TEMPLATE_${assessment.id}_${criterion.id}` ||
        definition.lessonId !== assessment.lessonId ||
        definition.rubricVersion !== assessment.version ||
        definition.prompt !== criterion.prompt ||
        definition.evidenceHint !== criterion.evidenceHint
      )
        throw new Error('TEMPLATE_CRITERION_DRIFT');
    }
  }
  if (count !== definitions.size) throw new Error('UNKNOWN_TEMPLATE');
  return bank;
}

/** Count only learner content, excluding labels and unchanged starter values. */
export function templateCompletion(raw: unknown, definition: TemplateDefinition) {
  const document = validateTemplateDocument(raw, definition);
  let characters = document.notes
    .replace(/^ {0,3}#{1,6}(?:[ \t]+.*)?$/gm, '')
    .replace(/^\s*(?:```.*|~~~.*|[-*_]{3,})\s*$/gm, '')
    .trim().length;
  let completedRows = 0;
  if (document.table && definition.kind === 'table') {
    const requiredIds = definition.starter.columns.map((column) => column.id);
    for (const [index, row] of document.table.rows.entries()) {
      let changed = false;
      for (const [columnIndex, value] of row.entries()) {
        const originalIndex = definition.starter.columns.findIndex(
          (column) => column.id === document.table!.columns[columnIndex].id,
        );
        const original = definition.starter.rows[index]?.[originalIndex] ?? '';
        if (value.trim() && value !== original) {
          characters += value.trim().length;
          changed = true;
        }
      }
      if (
        changed &&
        requiredIds.every((columnId) => {
          const columnIndex = document.table!.columns.findIndex((column) => column.id === columnId);
          return row[columnIndex]?.trim();
        })
      )
        completedRows++;
    }
  }
  return {
    characters,
    completedRows,
    ready:
      characters >= 80 && (definition.kind !== 'table' || completedRows >= definition.minimumRows),
  };
}

import {
  MAX_DOCUMENT_BYTES,
  MAX_ROWS,
  MAX_COLUMNS,
  validateTemplateDocument,
  templateCompletion,
  type TemplateDefinition,
  type TemplateDocument,
} from './schema';

function boundedInput(text: string) {
  if (new TextEncoder().encode(text).byteLength > MAX_DOCUMENT_BYTES)
    throw new Error('IMPORT_TOO_LARGE');
}
export function importTemplateJSON(text: string, definition: TemplateDefinition) {
  boundedInput(text);
  return validateTemplateDocument(JSON.parse(text.replace(/^\uFEFF/, '')), definition);
}
export function exportTemplateJSON(raw: unknown, definition: TemplateDefinition) {
  return JSON.stringify(validateTemplateDocument(raw, definition), null, 2) + '\n';
}

/** Safe spreadsheet export. JSON retains exact source values; CSV protects executable prefixes. */
export function exportTemplateCSV(raw: unknown, definition: TemplateDefinition) {
  const document = validateTemplateDocument(raw, definition);
  if (!document.table) throw new Error('TABLE_REQUIRED');
  const quote = (value: string) => {
    const safe = /^(?:\s*[=+\-@]|[\t\r])/.test(value) ? `'${value}` : value;
    return `"${safe.replace(/"/g, '""')}"`;
  };
  return (
    [document.table.columns.map((column) => column.label), ...document.table.rows]
      .map((row) => row.map(quote).join(','))
      .join('\r\n') + '\r\n'
  );
}

/** Strict bounded CSV: commas, escaped quotes, embedded newlines and CRLF; no guessed columns. */
export function readCSV(text: string): string[][] {
  boundedInput(text);
  const input = text.replace(/^\uFEFF/, '');
  const rows: string[][] = [];
  let row: string[] = [],
    field = '',
    quoted = false,
    closed = false;
  function endField() {
    row.push(field);
    if (row.length > MAX_COLUMNS) throw new Error('TOO_MANY_COLUMNS');
    field = '';
    closed = false;
  }
  function endRow() {
    endField();
    rows.push(row);
    row = [];
    if (rows.length > MAX_ROWS + 1) throw new Error('TOO_MANY_ROWS');
  }
  for (let i = 0; i < input.length; i++) {
    const character = input[i];
    if (quoted) {
      if (character === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          quoted = false;
          closed = true;
        }
      } else field += character;
    } else if (character === ',') endField();
    else if (character === '\n' || character === '\r') {
      if (character === '\r' && input[i + 1] === '\n') i++;
      endRow();
    } else if (character === '"') {
      if (field || closed) throw new Error('INVALID_CSV_QUOTE');
      quoted = true;
    } else {
      if (closed) throw new Error('INVALID_CSV_TRAILER');
      field += character;
    }
    if (field.length > 4000) throw new Error('CELL_TOO_LARGE');
  }
  if (quoted) throw new Error('UNCLOSED_CSV_QUOTE');
  if (row.length || field || closed) endRow();
  if (!rows.length) throw new Error('EMPTY_CSV');
  const width = rows[0].length;
  if (rows.some((values) => values.length !== width)) throw new Error('INVALID_ROW_WIDTH');
  return rows;
}
export function importTemplateCSV(
  text: string,
  raw: unknown,
  definition: TemplateDefinition,
): TemplateDocument {
  const document = validateTemplateDocument(raw, definition);
  if (!document.table) throw new Error('TABLE_REQUIRED');
  const [headers, ...rows] = readCSV(text);
  if (
    headers.length !== document.table.columns.length ||
    headers.some((label, i) => label !== document.table!.columns[i].label)
  )
    throw new Error('CSV_COLUMNS_MISMATCH');
  return validateTemplateDocument(
    {
      ...document,
      table: { ...document.table, rows },
    },
    definition,
  );
}

function markdownCell(value: string) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\\/g, '\\\\')
    .replace(/\|/g, '\\|')
    .replace(/\r\n|\r|\n/g, ' ⏎ ');
}
export function templateMarkdown(raw: unknown, definition: TemplateDefinition) {
  const document = validateTemplateDocument(raw, definition);
  if (!document.table) return document.notes;
  const table = document.table;
  const lines = [
    '| ' + table.columns.map((column) => markdownCell(column.label)).join(' | ') + ' |',
    '| ' + table.columns.map(() => '---').join(' | ') + ' |',
    ...table.rows.map((row) => '| ' + row.map(markdownCell).join(' | ') + ' |'),
  ];
  return lines.join('\n') + (document.notes ? '\n\n' + document.notes : '');
}

/** Existing assessment evidence limits still apply; filled formatting alone cannot qualify. */
export function templateSubmission(raw: unknown, definition: TemplateDefinition) {
  const document = validateTemplateDocument(raw, definition);
  if (!templateCompletion(document, definition).ready) throw new Error('TEMPLATE_INCOMPLETE');
  const text = templateMarkdown(document, definition);
  if (text.length > 12000) throw new Error('TEMPLATE_EVIDENCE_TOO_LONG');
  return { document, text };
}

'use client';
import { useEffect, useRef, useState } from 'react';
import type { VaultStatus } from '@/lib/vault/sync';

const errors: Record<string, string> = {
  VAULT_EDITED_NOTE:
    'העדכון נעצר כדי לא למחוק עריכה ידנית בקובץ שיוצא. גבה את העריכה והעבר אותה למחברת האישית לפני שחזור הקובץ המיוצא וניסיון נוסף.',
  VAULT_SYNC_BUSY: 'מפות Volt מתעדכנות בפעולה אחרת. נסה שוב לאחר סיומה.',
  VAULT_ACTIVE_CHANGED: 'גרסת הקורס השתנתה במהלך העדכון. נסה שוב כדי לייצא את הגרסה הפעילה.',
  UNAUTHORIZED: 'ההתחברות הסתיימה. היכנס שוב לחשבון כדי לעדכן את המפות.',
};

async function loadStatus(signal: AbortSignal): Promise<VaultStatus> {
  const response = await fetch('/api/vault/sync', { cache: 'no-store', signal });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'VAULT_STATUS_FAILED');
  return result;
}

/** Operator-only public projection controls; no browser paths or private notes are submitted. */
export function VaultSyncStatus() {
  const [status, setStatus] = useState<VaultStatus | null>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const running = useRef(false);
  useEffect(() => {
    const controller = new AbortController();
    loadStatus(AbortSignal.any([controller.signal, AbortSignal.timeout(20000)]))
      .then((result) => {
        if (!controller.signal.aborted) setStatus(result);
      })
      .catch(() => {
        if (!controller.signal.aborted)
          setError(
            'בדיקת גרסת הייצוא לא הושלמה. רענן את העמוד כדי לנסות לבדוק שוב. לעדכון המפות, השתמש בכפתור שבהמשך.',
          );
      });
    return () => controller.abort();
  }, []);

  async function synchronize() {
    if (running.current) return;
    running.current = true;
    setPending(true);
    setError('');
    setMessage('');
    let acknowledged = false;
    try {
      const response = await fetch('/api/vault/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: '{}',
        signal: AbortSignal.timeout(60000),
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || 'VAULT_SYNC_FAILED');
      acknowledged = true;
      setMessage(`מפות Volt עודכנו לגרסה ${result.curriculumVersion}.`);
      setStatus(await loadStatus(AbortSignal.timeout(20000)));
    } catch (cause) {
      const code = cause instanceof Error ? cause.message : '';
      setError(
        acknowledged
          ? 'המפות עודכנו, אך בדיקת המצב לא הושלמה. רענן את העמוד כדי לבדוק את הגרסה.'
          : errors[code] ||
              'לא התקבל אישור לעדכון המפות. רענן את העמוד ובדוק את הגרסה לפני ניסיון נוסף.',
      );
    } finally {
      running.current = false;
      setPending(false);
    }
  }

  return (
    <section className="card" aria-labelledby="vault-sync-title">
      <h2 id="vault-sync-title">מפת הידע ב־Volt</h2>
      <p>פרסום גרסת קורס או מאגר שאלות, וגם חזרה לגרסה קודמת, מפעילים עדכון של המפות והקשרים.</p>
      {status && (
        <div>
          <p>
            הגרסה באפליקציה: <bdi>{status.activeVersion}</bdi>
          </p>
          <p>
            גרסת הייצוא האחרונה: <bdi>{status.exportedVersion || 'טרם נשמרה'}</bdi>
          </p>
          <p role="status">
            {status.state === 'CURRENT'
              ? 'גרסת הייצוא השמור תואמת לקורס, למאגר השאלות ולהגדרות התבניות באפליקציה.'
              : status.state === 'PENDING'
                ? 'מפת הידע טרם עודכנה לקורס, למאגר השאלות ולהגדרות התבניות באפליקציה.'
                : 'לא ניתן היה לבדוק את הייצוא השמור.'}
          </p>
        </div>
      )}
      {!status && !error && <p role="status">בודק את גרסת הייצוא…</p>}
      <p>
        הבדיקה משווה את הקורס, את מאגר השאלות ואת הגדרות התבניות לייצוא השמור. היא אינה בודקת עריכות
        שנעשו בקבצים לאחר הייצוא.
      </p>
      {message && <p role="status">{message}</p>}
      {error && (
        <p role="alert" className="notice">
          {error}
        </p>
      )}
      <button
        className="button secondary"
        disabled={pending}
        aria-busy={pending}
        onClick={() => void synchronize()}
      >
        {pending ? 'מעדכן את המפות…' : 'לעדכן את מפות Volt'}
      </button>
    </section>
  );
}

