          <select value={week} onChange={(event) => setWeek(Number(event.target.value))}>
            {weeks.map((w) => (
              <option key={w.id} value={w.number}>
                שבוע {w.number} · {w.title}
              </option>
            ))}
          </select>
        </label>
      </div>
      <div className="map-foundation-banner">
        <span className="pill">
          {week === 1 ? 'מתחילים כאן · שבוע 1' : 'קודם בונים את היסודות'}
        </span>
        <p>פרק היסודות הוא נקודת ההתחלה. מסיימים את תרגילי החובה לפני שפותחים התמחות חדשה.</p>
        <Link href="/topics/CORE" className="text-link">
          לפרק היסודות ולסדר הלמידה ←
        </Link>
      </div>
      <div className="map-legend">
        <span>
          <i className="legend-built" /> הבנייה הושלמה
        </span>
        <span>
          <i className="legend-active" /> זמין ללמידה
        </span>
        <span>
          <i className="legend-locked" /> אחרי פרק היסודות
        </span>
      </div>
      <div className="node-path" dir="ltr">
        <svg viewBox="0 0 500 170" preserveAspectRatio="none" aria-hidden="true">
          <path d="M50 55 H100 V110 H200 V55 H300 V110 H400 V55 H450" />
        </svg>
        {visible.map((lesson, i) => {
          const state = lockedIds.includes(lesson.id)
            ? 'locked'
            : built.has(lesson.id)
              ? 'built'
              : lesson.publicationStatus === 'published'
                ? 'active'
                : 'locked';
          return (
            <button
              key={lesson.id}
              className={`map-node ${state} ${selected.id === lesson.id ? 'selected' : ''}`}
              style={
                {
                  '--node-x': `${10 + i * 20}%`,
                  '--node-y': `${i % 2 ? 110 : 55}px`,
                } as CSSProperties
              }
              onClick={() => setSelectedId(lesson.id)}
              aria-pressed={selected.id === lesson.id}
              aria-label={`יום ${lesson.day}: ${lesson.title} · ${state === 'built' ? 'הבנייה הושלמה' : state === 'active' ? 'זמין' : 'נעול עד להשלמת פרק היסודות'}`}
            >
              <span className="node-ring">
                {state === 'built' ? (
                  <Check size={21} />
                ) : state === 'active' ? (
                  <Play size={19} fill="currentColor" />
                ) : (
                  <LockKeyhole size={17} />
                )}
              </span>
              <span className="node-caption" dir="rtl">
                יום {String(lesson.day).padStart(2, '0')}
              </span>
            </button>
          );
        })}
      </div>
      <div className="map-selected" aria-live="polite">
        <div>
          <span className="eyebrow">DAY {String(selected.day).padStart(2, '0')}</span>
          <h3 dir="auto">{selected.title}</h3>
          <span className="muted">
            <Clock3 size={13} /> עד {selected.estimatedMinutes} דקות{' '}
            {lockedIds.includes(selected.id) ? '· נפתח אחרי תרגילי פרק היסודות' : ''}
          </span>
        </div>
        <Link
          href={lockedIds.includes(selected.id) ? '/topics/CORE' : `/learn/${selected.id}`}
          className={`button ${selected.publicationStatus === 'published' ? 'primary' : 'secondary'}`}
        >
          {lockedIds.includes(selected.id)
            ? 'להשלמת פרק היסודות'
            : selected.publicationStatus === 'published'
              ? 'מעבר לשיעור'
              : 'צפייה במתווה'}
          <ArrowLeft size={16} />
        </Link>
      </div>
    </section>
  );
}

'use client';
import { useActionState, useCallback, useEffect, useRef, useState } from 'react';
import Link from '@/components/workspace-navigation';
import { Check, ArrowLeft, ArrowRight } from 'lucide-react';
import type { Assessment } from '@/lib/curriculum/assessment';
import { submitEvidence } from '@/app/assessments/actions';
import { ArtifactPicker, type SelectedArtifact } from './assessment/artifact-picker';
import { PortfolioCard } from './assessment/portfolio-card';
import { reducedMotion } from '@/lib/domain/motion';
import { ReinforcementQuiz } from './assessment/reinforcement-quiz';
import { TemplateWorkspace, type InitialWorkspace } from './assessment/workspace/workspace';
import { templateSubmission } from '@/lib/templates/formats';
import type { PublicPracticeQuestion } from '@/lib/quizzes/catalog';

export function AssessmentForm({
  assessment,
  submissionId,
  curriculumVersion,
  built,
  practiceQuestion,
  templateDrafts,
}: {
  assessment: Assessment;
  submissionId: string;
  curriculumVersion: string;
  built: boolean;
  practiceQuestion: PublicPracticeQuestion;
  templateDrafts: InitialWorkspace[];
}) {
  // Preserve retry identity across unrelated Server Action revalidation.
  const [ownedSubmissionId] = useState(submissionId);
  const [templateModes, setTemplateModes] = useState<Record<string, boolean>>({});
  const [templateStates, setTemplateStates] = useState<
    Record<string, { revision: number; ready: boolean }>
  >(() =>
    Object.fromEntries(
      templateDrafts.map((draft) => {
        let ready = false;
        try {
          templateSubmission(draft.document, draft.definition);
          ready = draft.revision > 0 && !draft.readOnly;
        } catch {}
        return [draft.definition.id, { revision: draft.revision, ready }];
      }),
    ),
  );
  const updateTemplateState = useCallback(
    (id: string, state: { revision: number; ready: boolean }) => {
      setTemplateStates((previous) =>
        previous[id]?.revision === state.revision && previous[id]?.ready === state.ready
          ? previous
          : { ...previous, [id]: state },
      );
    },
    [],
  );
  const selectedTemplates = templateDrafts.filter(
    (draft) => templateModes[draft.definition.criterionId],
  );
  const templateReferences = selectedTemplates.map((draft) => ({
    templateId: draft.definition.id,
    definitionHash: draft.definitionHash,
    revision: templateStates[draft.definition.id]?.revision || 0,
  }));
  const [openedTemplates, setOpenedTemplates] = useState<Record<string, boolean>>({});
  const [evidence, setEvidence] = useState<Record<string, string>>({});
  const [files, setFiles] = useState<SelectedArtifact[]>([]);
  const [index, setIndex] = useState(0),
    [included, setIncluded] = useState(false),
    [title, setTitle] = useState(assessment.title),
    [summary, setSummary] = useState(''),
    [feedback, setFeedback] = useState('');
  const heading = useRef<HTMLHeadingElement>(null),
    moved = useRef(false);
  const [result, action, pending] = useActionState(
    async (previous: { ok: boolean; message: string }, form: FormData) => {
      for (const item of files) form.append(`artifact:${item.criterionId}:${item.id}`, item.file);
      try {
        return await submitEvidence(previous, form);
      } catch {
        return {
          ok: false,
          message:
            'לא התקבל אישור להגשה. התשובות עדיין כאן; נסה להגיש שוב כדי לבדוק אם העבודה נשמרה.',
        };
      }
    },
    { ok: true, message: '' },
  );
  const submitted = result.ok && Boolean(result.message),
    disabled = !built || pending || submitted;
  const valid = (id: string) => {
    const draft = templateDrafts.find((item) => item.definition.criterionId === id);
    return templateModes[id] && draft
      ? Boolean(templateStates[draft.definition.id]?.ready)
      : (evidence[id]?.trim().length || 0) >= 80 && (evidence[id]?.length || 0) <= 12000;
  };
  const ready = assessment.criteria.filter((item) => valid(item.id)).length;
  function go(next: number) {
    moved.current = true;
    setIndex(next);
    setFeedback('');
  }
  useEffect(() => {
    if (!moved.current) return;
    heading.current?.focus({ preventScroll: true });
    heading.current?.scrollIntoView({
      block: 'start',
      behavior: reducedMotion() ? 'instant' : 'smooth',
    });
  }, [index]);
  return (
    <section className="card assessment-card" id="assessment">
      <p className="eyebrow">הוכחה מעשית · צעד אחר צעד</p>
      <h2>{assessment.title}</h2>
      <p className="muted">{assessment.instructions}</p>
      <p className="notice">
        ממלאים תשובה אחת בכל פעם. אפשר לחזור לכל שאלה. הבדיקה כאן בודקת שהמילוי הושלם; בודק מורשה
        יעריך את העבודה לאחר ההגשה.
      </p>
      {!built && (
        <p className="muted">
          השאלות זמינות לקריאה. כדי לענות ולהגיש, השלם קודם את תרגיל הבנייה וסמן אותו כהושלם בשיעור.
        </p>
      )}
      <ReinforcementQuiz
        key={`${assessment.lessonId}:${practiceQuestion.hash}`}
        lessonId={assessment.lessonId}
        curriculumVersion={curriculumVersion}
        question={practiceQuestion}
      />
      <div className="assessment-progress">
        <span>
          שאלה {index + 1} מתוך {assessment.criteria.length}
        </span>
        <span>תשובות מוכנות להגשה: {ready}</span>
        <progress value={ready} max={assessment.criteria.length} aria-label="השלמת תשובות להערכה" />
      </div>
      <nav className="assessment-question-nav" aria-label="מעבר בין שאלות ההערכה">
        {assessment.criteria.map((item, i) => (
          <button
            type="button"
            key={item.id}
            aria-label={`שאלה ${i + 1}${valid(item.id) ? ' · המילוי הושלם' : ''}`}
            aria-current={i === index ? 'step' : undefined}
            onClick={() => go(i)}
            disabled={pending}
          >
            <span>{i + 1}</span>
            {valid(item.id) && <Check aria-hidden="true" size={14} />}
          </button>
        ))}
      </nav>
      <form
        action={action}
        // Keep answer and portfolio selections intact after any resolved action, including a lost acknowledgement.
        onReset={(event) => event.preventDefault()}
        noValidate
        onSubmit={(event) => {
          setFeedback('');
          if (files.length + selectedTemplates.length > 6) {
            event.preventDefault();
            setFeedback(
              'אפשר לצרף עד 6 קבצים בסך הכול, כולל התבניות שנבחרו. הסר קובץ או בטל בחירת תבנית ונסה שוב.',
            );
            return;
          }
          const invalid = assessment.criteria.findIndex((item) => !valid(item.id));
          if (invalid >= 0) {
            event.preventDefault();
            go(invalid);
            setFeedback('ההגשה לא נשמרה. השלם כל סעיף וודא שהתבניות שבחרת מוכנות ושמורות בחשבון.');
          }
        }}
      >
        <input type="hidden" name="submissionId" value={ownedSubmissionId} />
        <input type="hidden" name="assessmentId" value={assessment.id} />
        <input type="hidden" name="rubricVersion" value={assessment.version} />
        <input type="hidden" name="curriculumVersion" value={curriculumVersion} />
        {selectedTemplates.length > 0 && (
          <input
            type="hidden"
            name="templateReferences"
            value={JSON.stringify(templateReferences)}
          />
        )}
        <fieldset disabled={disabled}>
          {assessment.criteria.map((item, i) => (
            <section
              className="evidence-field assessment-question"
              hidden={i !== index}
              key={item.id}
              data-mentor-kind="assessment"
              data-mentor-id={item.id}
              data-mentor-title={item.prompt}
            >
              <span className="question-type">
                {/הרצ|בדיק|תקלה|כשל/.test(item.prompt)
                  ? 'בדיקה מעשית + קבצים'
                  : 'הסבר במילים שלך + קבצים'}
              </span>
              <h3 ref={i === index ? heading : undefined} tabIndex={-1}>
                {item.prompt}
              </h3>
              <label htmlFor={item.id}>
                {i + 1}. {item.prompt}
              </label>
              <p id={`${item.id}-help`} className="muted">
                {item.evidenceHint} (80–12,000 תווים)
              </p>
              <textarea
                hidden={Boolean(templateModes[item.id])}
                value={evidence[item.id] ?? ''}
                onChange={(event) =>
                  setEvidence((previous) => ({ ...previous, [item.id]: event.target.value }))
                }
                id={item.id}
                name={`evidence:${item.id}`}
                aria-describedby={`${item.id}-help ${item.id}-feedback`}
                minLength={80}
                maxLength={12000}
                rows={6}
                required
                dir="auto"
              />
              <p id={`${item.id}-feedback`} className="answer-feedback" role="status">
                {valid(item.id)
                  ? 'המילוי הושלם. איכות התשובה תיבדק לאחר ההגשה.'
                  : templateModes[item.id]
                    ? 'השלם את התבנית והמתן לאישור השמירה.'
                    : `עוד ${Math.max(0, 80 - (evidence[item.id]?.trim().length || 0))} תווים לפחות כדי לתאר את העבודה.`}
              </p>
              <label className="toggle-row">
                <input
                  type="checkbox"
                  checked={Boolean(templateModes[item.id])}
                  onChange={(event) => {
                    setTemplateModes((previous) => ({
                      ...previous,
                      [item.id]: event.target.checked,
                    }));
                    if (event.target.checked)
                      setOpenedTemplates((previous) => ({ ...previous, [item.id]: true }));
                  }}
                />
                להגיש את סעיף {i + 1} מתוך התבנית
              </label>
              {templateModes[item.id] && (
                <p className="muted">
                  הטיוטה השמורה תשמש כתשובה. עותק קבוע שלה יצורף כקובץ להגשה. הטקסט שכתבת ידנית נשאר
                  בנפרד; ביטול הבחירה יחזיר אותך אליו.
                </p>
              )}
              <details open={templateModes[item.id] ? true : undefined}>
                <summary
                  onClick={() =>
                    setOpenedTemplates((previous) => ({ ...previous, [item.id]: true }))
                  }
                >
                  לעבוד בתבנית בתוך השיעור
                </summary>
                {openedTemplates[item.id] &&
                  templateDrafts.find((d) => d.definition.criterionId === item.id) && (
                    <TemplateWorkspace
                      initial={templateDrafts.find((d) => d.definition.criterionId === item.id)!}
                      curriculumVersion={curriculumVersion}
                      disabled={disabled}
                      onSubmissionState={updateTemplateState}
                      onUse={(text) =>
                        setEvidence((previous) => ({ ...previous, [item.id]: text }))
                      }
                    />
                  )}
              </details>
              <ArtifactPicker
                criterionId={item.id}
                files={files}
                onChange={setFiles}
                disabled={disabled}
              />
            </section>
          ))}
          <div className="assessment-navigation">
            <button
              className="button secondary"
              type="button"
              disabled={index === 0}
              onClick={() => go(index - 1)}
            >
              <ArrowRight size={16} />
              השאלה הקודמת
            </button>
            <button
              className="button primary"
              type="button"
              disabled={index === assessment.criteria.length - 1}
              onClick={() => go(index + 1)}
            >
              השאלה הבאה
              <ArrowLeft size={16} />
            </button>
          </div>
          <details className="portfolio-options">
            <summary>להציג את העבודה בתיק העבודות שלי</summary>
            <label className="toggle-row">
              <input
                type="checkbox"
                name="portfolioIncluded"
                checked={included}
                onChange={(event) => setIncluded(event.target.checked)}
              />
              לכלול את ההגשה בתיק העבודות הפרטי שלי
            </label>
            <label className="field-label">
              שם העבודה
              <input
                name="portfolioTitle"
                value={title}
                onChange={(event) => setTitle(event.target.value)}
                maxLength={120}
                required
              />
            </label>
            <label className="field-label">
              מה בניתי ומה למדתי?
              <textarea
                name="portfolioSummary"
                value={summary}
                onChange={(event) => setSummary(event.target.value)}
                maxLength={1200}
                rows={3}
              />
            </label>
            <PortfolioCard
              title={title}
              summary={summary}
              status={submitted ? 'ממתינה להערכה' : 'טיוטה · עדיין לא הוגשה'}
              fileCount={files.length + selectedTemplates.length}
              preview
            />
          </details>
          <p className="muted">
            קבצים שנבחרו להגשה: {files.length + selectedTemplates.length} (כולל תבניות שנבחרו).
            הקבצים יישמרו בחשבון שלך עם התשובות; אפשר להוריד אותם לאחר ההגשה.
          </p>
          <button className="button primary" type="submit">
            {pending
              ? 'שומר תשובות וקבצים…'
              : submitted
                ? 'הראיות הוגשו'
                : selectedTemplates.length
                  ? 'הגש מתוך הטמפלייט'
                  : 'הגשת ראיות להערכה'}
          </button>
        </fieldset>
        <p role="status" className={result.ok ? 'form-status' : 'form-error'}>
          {feedback || result.message}
        </p>
      </form>
      <Link className="text-link" href="/assessments">
        לעבודות שהגשתי ולמשוב ←
      </Link>
      {submitted && (
        <Link href="/portfolio" className="button secondary">
          לתיק העבודות שלי
        </Link>
      )}
    </section>
  );
}

'use client';
import { useEffect, useRef, useState, type FormEvent } from 'react';
import Link from '@/components/workspace-navigation';
import { useRouter } from 'next/navigation';
import type { quizReviewStore } from '@/lib/quizzes/review-store';
import { reducedMotion } from '@/lib/domain/motion';
import { VaultSyncStatus } from './vault-sync-status';

type Store = ReturnType<typeof quizReviewStore>;
type Overview = ReturnType<Store['list']> & {
  status: ReturnType<Store['status']>;
  draft: { hash: string; version: string; curriculumVersion: string; questionCount: number };
};
type Detail = ReturnType<Store['details']>;
type Question = ReturnType<Store['question']>;
const failures: Record<string, string> = {
  INVALID_REQUEST:
    'בדוק שכל השדות מולאו. אישור דורש סימון של שלוש הבדיקות והסבר של 40 תווים לפחות.',
  UNAUTHORIZED: 'ההתחברות הסתיימה. היכנס שוב לחשבון.',
  QUIZ_REVIEW_STALE_COURSE: 'גרסת הקורס השתנתה. יש להכין בדיקה חדשה מול השיעורים העדכניים.',
  QUIZ_REVIEW_STALE_DRAFT: 'טיוטת השאלות השתנתה. רענן את העמוד לפני הכנת בדיקה חדשה.',
  QUIZ_REVIEW_STALE_PROPOSAL: 'הבקשה אינה תואמת לבדיקה השמורה. רענן את העמוד.',
  QUIZ_REVIEW_STALE_QUESTION: 'הבקשה אינה תואמת לשאלה השמורה. טען אותה מחדש.',
  QUIZ_REVIEW_ALREADY_DECIDED: 'כבר נשמרה החלטה לשאלה הזו. שינוי בהחלטה דורש בדיקה חדשה.',
  QUIZ_REVIEW_INCOMPLETE:
    'אי אפשר לפרסם לפני שכל השאלות אושרו. שאלה שנדחתה דורשת תיקון ובדיקה חדשה.',
  QUIZ_REVIEW_VERSION_ORDER: 'בחר מספר גרסה גבוה יותר מגרסת השאלות הפעילה.',
  QUIZ_REVIEW_VERSION_USED:
    'מספר הגרסה כבר נשמר. בחר מספר חדש; גרסאות קודמות נשמרות גם לאחר חזרה לגרסה קודמת.',
  QUIZ_REVIEW_STALE_RELEASE: 'גרסת השאלות הפעילה השתנתה. רענן לפני חזרה לגרסה הקודמת.',
  QUIZ_REVIEW_RELEASE_CONFLICT: 'מספר הגרסה כבר שייך לבדיקה אחרת. הכן בדיקה חדשה עם מספר גרסה חדש.',
  QUIZ_REVIEW_REQUEST_CONFLICT:
    'אותה בקשה כבר נשמרה עם פרטים אחרים. רענן את העמוד לפני פעולה נוספת.',
  QUIZ_REVIEW_BUSY: 'פעולת שמירה אחרת מתבצעת כרגע. נסה שוב לאחר סיומה.',
};
async function read<T>(query = '', signal = AbortSignal.timeout(20000)): Promise<T> {
  const response = await fetch(`/api/quizzes/review${query}`, { cache: 'no-store', signal });
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'REQUEST_FAILED');
  return result as T;
}

export function QuizBankReview({ initial }: { initial: Overview }) {
  const router = useRouter();
  const [overview, setOverview] = useState(initial),
    [detail, setDetail] = useState<Detail | null>(null);
  const [index, setIndex] = useState(0),
    [question, setQuestion] = useState<Question | null>(null);
  const [vaultRevision, setVaultRevision] = useState(0);
  const [questionLoading, setQuestionLoading] = useState(false),
    [pending, setPending] = useState(false);
  const [message, setMessage] = useState(''),
    [error, setError] = useState(''),
    [retry, setRetry] = useState(false);
  const running = useRef(false),
    savedRequest = useRef<unknown>(null),
    heading = useRef<HTMLHeadingElement>(null);
  const proposalId = detail?.proposal.id,
    questionId = detail?.proposal.bank.quizzes[index]?.id;
  const reviewCurrent = detail?.current;
  useEffect(() => {
    if (!proposalId || !questionId || !reviewCurrent) return;
    const controller = new AbortController();
    read<Question>(
      `?proposalId=${proposalId}&questionId=${encodeURIComponent(questionId)}`,
      AbortSignal.any([controller.signal, AbortSignal.timeout(20000)]),
    )
      .then((result) => {
        if (controller.signal.aborted) return;
        setQuestion(result);
        setQuestionLoading(false);
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setQuestionLoading(false);
          setError('לא ניתן לטעון את קטע השיעור כרגע. פתח את הבדיקה מחדש כדי לנסות שוב.');
        }
      });
    return () => controller.abort();
  }, [proposalId, questionId, reviewCurrent]);
  async function show(id: string) {
    if (running.current) return;
    setError('');
    setDetail(null);
    setQuestion(null);
    setQuestionLoading(true);
    try {
      const loaded = await read<Detail>(`?proposalId=${id}`);
      setDetail(loaded);
      setIndex(0);
      if (!loaded.current) setQuestionLoading(false);
    } catch {
      setQuestionLoading(false);
      setError('לא ניתן לטעון את הבדיקה. נסה לפתוח אותה שוב.');
    }
  }
  function go(next: number) {
    if (!detail || next < 0 || next >= detail.proposal.bank.quizzes.length || next === index)
      return;
    setQuestion(null);
    setQuestionLoading(detail.current);
    setIndex(next);
    setError('');
    heading.current?.focus({ preventScroll: true });
    heading.current?.scrollIntoView({
      block: 'start',
      behavior: reducedMotion() ? 'instant' : 'smooth',
    });
  }
  async function mutate(payload: unknown, success: string) {
    if (running.current) return;
    running.current = true;
    savedRequest.current = payload;
    setPending(true);
    setError('');
    setMessage('');
    setRetry(false);
    try {
      const response = await fetch('/api/quizzes/review', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        signal: AbortSignal.timeout(60000),
      });
      const result = await response.json();
      if (!response.ok) throw new Error(result.error || 'REQUEST_FAILED');
      savedRequest.current = null;
      setMessage(
        success +
          (result.vaultSync
            ? result.vaultSync.status === 'SYNCED'
              ? ' מפות Volt עודכנו.'
              : ' המפות לא עודכנו. בדוק את מצב המפה ונסה לעדכן בנפרד.'
            : ''),
      );
      if (result.vaultSync) setVaultRevision((value) => value + 1);
      setOverview(await read<Overview>());
      const newId = result.proposal?.id || proposalId;
      if (newId) {
        setDetail(await read<Detail>(`?proposalId=${newId}`));
        if (newId !== proposalId) {
          setIndex(0);
          setQuestion(null);
          setQuestionLoading(true);
        }
      }
      router.refresh();
    } catch (cause) {
      const code = cause instanceof Error ? cause.message : '';
      setError(
        failures[code] ||
          (savedRequest.current
            ? 'לא התקבל אישור לשמירה. אפשר לחזור על אותה בקשה באמצעות כפתור הניסיון הנוסף.'
            : 'הפעולה נשמרה, אך העמוד לא התרענן. רענן כדי לראות את התוצאה.'),
      );
      setRetry(Boolean(savedRequest.current) && !failures[code]);
    } finally {
      running.current = false;
      setPending(false);
    }
  }
  function propose(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void mutate(
      {
        operation: 'propose',
        requestId: crypto.randomUUID(),
        targetVersion: new FormData(event.currentTarget).get('targetVersion'),
        draftHash: overview.draft.hash,
        curriculumHash: overview.status.curriculumHash,
      },
      'הבדיקה נשמרה. יצירת הבדיקה אינה מפרסמת את מאגר השאלות.',
    );
  }
  function decide(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!detail || !question) return;
    const form = new FormData(event.currentTarget);
    void mutate(
      {
        operation: 'decide',
        input: {
          proposalId,
          proposalHash: detail.proposalHash,
          questionId,
          questionHash: question.context.questionHash,
          decision: form.get('decision'),
          notes: form.get('notes'),
          answerChecked: form.get('answerChecked') === 'on',
          sourcesChecked: form.get('sourcesChecked') === 'on',
          hebrewChecked: form.get('hebrewChecked') === 'on',
        },
      },
      'ההחלטה נשמרה. אישור שאלה אינו מפרסם את מאגר השאלות; הפרסום נעשה בכפתור נפרד.',
    );
  }
  const approved =
    detail?.decisions.filter((item) => item?.input.decision === 'approve').length || 0;
  const rejected =
    detail?.decisions.filter((item) => item?.input.decision === 'reject').length || 0;
  const count = detail?.proposal.bank.quizzes.length || 0;
  const selectedDecision = detail?.decisions[index];
  const currentQuestion = detail?.proposal.bank.quizzes[index];
  const [major, minor, patch] = (overview.status.reservedVersion || overview.draft.version)
    .split('.')
    .map(Number);
  const target = overview.status.reservedVersion
    ? patch < 9999
      ? `${major}.${minor}.${patch + 1}`
      : minor < 9999
        ? `${major}.${minor + 1}.0`
        : `${major + 1}.0.0`
    : overview.draft.version;
  return (
    <>
      <div className="notice">
        <strong>
          גרסת הקורס: <bdi>{overview.status.curriculumVersion}</bdi>
        </strong>
        <p>
          {overview.status.active
            ? `גרסת השאלות הפעילה: ${overview.status.active.version}${overview.status.available ? '' : ' · אינה תואמת לקורס הנוכחי ואינה מוצגת ללומדים'}.`
            : 'טרם פורסם מאגר שאלות ייעודי לשיעורים.'}
        </p>
        <p>
          אישור השאלות דורש בדיקת תוכן אנושית. בדיקות אוטומטיות בודקות מבנה וקישורים, ואינן מאשרות
          תשובות.
        </p>
      </div>
      <VaultSyncStatus key={vaultRevision} />
      {message && (
        <p role="status" className="notice">
          {message}
        </p>
      )}
      {error && (
        <div role="alert" className="notice">
          <p>{error}</p>
          {retry && (
            <button
              type="button"
              className="button secondary"
              disabled={pending}
              onClick={() => void mutate(savedRequest.current, 'הפעולה נשמרה.')}
            >
              לנסות שוב את אותה בקשה
            </button>
          )}
        </div>
      )}
      <section className="card auditor-authoring">
        <h2>הכנת בדיקה חדשה</h2>
        <p>
          הטיוטה כוללת {overview.draft.questionCount} שאלות לגרסת הקורס{' '}
          <bdi>{overview.draft.curriculumVersion}</bdi>. כל החלטה תשמור את נוסח השאלה שנבדק.
        </p>
        <form className="auditor-form" onSubmit={propose}>
          <fieldset
            disabled={
              pending || overview.draft.curriculumVersion !== overview.status.curriculumVersion
            }
          >
            <label>
              מספר הגרסה לפרסום
              <input
                key={target}
                name="targetVersion"
                defaultValue={target}
                pattern="[0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,4}"
                required
                dir="ltr"
              />
            </label>
            <button type="submit" className="button primary">
              להכין בדיקה חדשה
            </button>
          </fieldset>
        </form>
        {overview.draft.curriculumVersion !== overview.status.curriculumVersion && (
          <p className="notice">
            הטיוטה מתייחסת לגרסת קורס אחרת. יש לעדכן אותה ולבדוק את הקשרים לשיעורים לפני הכנת בדיקה
            חדשה.
          </p>
        )}
      </section>
      <section className="card auditor-proposals">
        <h2>בדיקות שמורות</h2>
        {!overview.proposals.length && <p>עדיין אין בדיקות שמורות.</p>}
        <ul>
          {overview.proposals.map((item) => (
            <li key={item.id}>
              <span>
                גרסה <bdi>{item.targetVersion}</bdi> · {item.questionCount} שאלות ·{' '}
                {new Date(item.createdAt).toLocaleDateString('he-IL', {
                  timeZone: 'Asia/Jerusalem',
                })}
              </span>
              <button
                type="button"
                className="button secondary"
                disabled={pending}
                onClick={() => void show(item.id)}
              >
                לפתוח בדיקה
              </button>
            </li>
          ))}
        </ul>
        {overview.total > 100 && (
          <p>מוצגות 100 הבדיקות האחרונות. בדיקות ישנות נשמרות ולא נמחקות.</p>
        )}
      </section>
      {detail && (
        <section className="card auditor-detail quiz-review-question">
          <h2 ref={heading} tabIndex={-1}>
            בדיקת שאלות · גרסה <bdi>{detail.proposal.targetVersion}</bdi>
          </h2>
          <div className="quiz-review-progress">
            <span>
              {approved} מתוך {count} שאלות אושרו · {rejected} נדחו
            </span>
            <progress value={approved} max={count} aria-label="שאלות שאושרו לפרסום" />
          </div>
          {!detail.current && (
            <p className="notice">
              גרסת הקורס השתנתה מאז הכנת הבדיקה. ההחלטות נשמרו, אך אי אפשר לאשר או לפרסם אותה מול
              הקורס הנוכחי.
            </p>
          )}
          <div className="auditor-form">
            <label>
              מעבר לשאלה לפי מספר
              <select
                value={index}
                aria-label="מעבר לשאלה לפי מספר"
                disabled={pending}
                onChange={(event) => go(Number(event.target.value))}
              >
                {detail.proposal.bank.quizzes.map((item, i) => (
                  <option key={item.id} value={i}>
                    {i + 1}. {item.lessonId}
                    {detail.decisions[i]
                      ? detail.decisions[i]?.input.decision === 'approve'
                        ? ' · אושרה'
                        : ' · נדחתה'
                      : ''}
                  </option>
                ))}
              </select>
            </label>
          </div>
          <p>
            שאלה {index + 1} מתוך {count}
          </p>
          <h3>{currentQuestion?.question}</h3>
          {currentQuestion?.options.map((option) => (
            <p
              className="quiz-review-answer"
              data-correct={option.id === currentQuestion.correctOptionId}
              key={option.id}
            >
              <bdi>{option.id}</bdi> · {option.text}
              {option.id === currentQuestion.correctOptionId && (
                <strong> · התשובה המסומנת בטיוטה</strong>
              )}
            </p>
          ))}
          <p>
            <strong>ההסבר המוצע:</strong> {currentQuestion?.explanation}
          </p>
          {questionLoading && <p role="status">טוען את הקטע הרלוונטי מהשיעור…</p>}
          {question && (
            <>
              <h3>הקטע מהשיעור: {question.lessonTitle}</h3>
              <Link
                className="text-link"
                href={`/learn/${question.question.lessonId}`}
                target="_blank"
              >
                לפתיחת השיעור המלא בחלון חדש
              </Link>
              <pre className="auditor-original" tabIndex={0} aria-label="הקטע מהשיעור לבדיקת השאלה">
                {question.sourceText}
              </pre>
              <h3>מקורות לבדיקה</h3>
              <ul>
                {question.context.sources.map((source) => (
                  <li key={source.id}>
                    <a href={source.url} target="_blank" rel="noopener noreferrer">
                      {source.title}
                      <span className="sr-only"> · נפתח בחלון חדש</span>
                    </a>
                  </li>
                ))}
              </ul>
            </>
          )}
          {selectedDecision ? (
            <div className="notice">
              <strong>
                {selectedDecision.input.decision === 'approve'
                  ? 'השאלה אושרה בבדיקה הזו.'
                  : 'השאלה נדחתה בבדיקה הזו.'}
              </strong>
              <p>{selectedDecision.input.notes}</p>
              <p>ההחלטה נשמרה ואינה ניתנת להחלפה. שינוי בנוסח או בהחלטה דורש בדיקה חדשה.</p>
            </div>
          ) : (
            <form className="auditor-form" key={`${proposalId}:${questionId}`} onSubmit={decide}>
              <fieldset disabled={pending || !detail.current || !question || questionLoading}>
                <legend>החלטה לגבי השאלה הזו</legend>
                <label>
                  החלטה
                  <select name="decision" aria-label="החלטה" defaultValue="reject">
                    <option value="reject">לדחות עד לתיקון</option>
                    <option value="approve">לאשר את הנוסח שנבדק</option>
                  </select>
                </label>
                <label className="auditor-check">
                  <input type="checkbox" name="answerChecked" />
                  בדקתי את השאלה, את כל האפשרויות ואת ההסבר לתשובה.
                </label>
                <label className="auditor-check">
                  <input type="checkbox" name="sourcesChecked" />
                  קראתי את המקורות ובדקתי שהם תומכים בתשובה המסומנת.
                </label>
                <label className="auditor-check">
                  <input type="checkbox" name="hebrewChecked" />
                  בדקתי שהעברית תקינה ושהניסוח ברור ללומד.
                </label>
                <label>
                  הסבר להחלטה
                  <textarea name="notes" minLength={40} maxLength={4000} required rows={4} />
                </label>
                <button type="submit" className="button primary">
                  לשמור החלטה לשאלה
                </button>
              </fieldset>
            </form>
          )}
          <nav className="assessment-navigation" aria-label="ניווט בבדיקת השאלות">
            <button
              type="button"
              className="button secondary"
              disabled={pending || index === 0}
              onClick={() => go(index - 1)}
            >
              השאלה הקודמת
            </button>
            <button
              type="button"
              className="button secondary"
              disabled={pending || index === count - 1}
              onClick={() => go(index + 1)}
            >
              השאלה הבאה
            </button>
          </nav>
          <div className="auditor-publication">
            <h3>פרסום ללומדים</h3>
            <p>
              פרסום מחליף את גרסת השאלות הפעילה. תשובות שכבר נשמרו, נקודות והתקדמות נשארות בחשבון.
            </p>
            <button
              type="button"
              className="button primary"
              disabled={
                pending ||
                !detail.current ||
                approved !== count ||
                overview.status.active?.version === detail.proposal.targetVersion
              }
              onClick={() =>
                void mutate(
                  {
                    operation: 'publish',
                    proposalId,
                    proposalHash: detail.proposalHash,
                    requestId: crypto.randomUUID(),
                  },
                  'גרסת השאלות המאושרת פורסמה ללומדים.',
                )
              }
            >
              לפרסם את כל השאלות המאושרות
            </button>
            {overview.status.active?.version === detail.proposal.targetVersion && (
              <button
                type="button"
                className="button secondary"
                disabled={pending}
                onClick={() =>
                  void mutate(
                    {
                      operation: 'rollback',
                      requestId: crypto.randomUUID(),
                      releaseHash: overview.status.active!.releaseHash,
                    },
                    'המערכת חזרה לגרסת השאלות הקודמת. התשובות וההתקדמות נשמרו.',
                  )
                }
              >
                לחזור לגרסת השאלות הקודמת
              </button>
            )}
          </div>
        </section>
      )}
    </>
  );
}

'use client';
import { useEffect, useRef, useState } from 'react';
import { FileUp, X, RefreshCw } from 'lucide-react';
import Image from 'next/image';
import {
  artifactAccept,
  artifactExtensions,
  MAX_FILES,
  MAX_FILE_BYTES,
  MAX_TOTAL_BYTES,
} from '@/lib/domain/artifacts';
export type SelectedArtifact = { id: string; criterionId: string; file: File };

function FilePreview({ file }: { file: File }) {
  const [preview, setPreview] = useState<{ url?: string; text?: string }>({});
  useEffect(() => {
    let active = true;
    const url = ['image/png', 'image/jpeg'].includes(file.type)
      ? URL.createObjectURL(file)
      : undefined;
    if (url)
      Promise.resolve().then(() => {
        if (active) setPreview({ url });
      });
    else if (!/\.pdf$/i.test(file.name))
      file
        .slice(0, 2400)
        .text()
        .then((text) => {
          if (active) setPreview({ text });
        });
    return () => {
      active = false;
      if (url) URL.revokeObjectURL(url);
    };
  }, [file]);
  // Object URLs stay local; Next image optimization would require a remote request.
  return preview.url ? (
    <Image
      unoptimized
      width={400}
      height={240}
      src={preview.url}
      alt={`תצוגה מקדימה של ${file.name}`}
      className="artifact-image"
    />
  ) : preview.text ? (
    <pre className="artifact-code" dir="auto">
      {preview.text}
      {file.size > 2400 ? '\n… תצוגה מקדימה חלקית' : ''}
    </pre>
  ) : (
    <p className="muted">לא מוצגת כרגע תצוגה מקדימה. פרטי הקובץ מופיעים למעלה.</p>
  );
}
export function ArtifactPicker({
  criterionId,
  files,
  onChange,
  disabled,
}: {
  criterionId: string;
  files: SelectedArtifact[];
  onChange: (files: SelectedArtifact[]) => void;
  disabled: boolean;
}) {
  const picker = useRef<HTMLInputElement>(null);
  const [error, setError] = useState(''),
    [dragging, setDragging] = useState(false),
    [replaceId, setReplaceId] = useState<string>();
  function add(newFiles: File[], replacement?: string) {
    const retained = replacement ? files.filter((item) => item.id !== replacement) : files;
    if (
      retained.length + newFiles.length > MAX_FILES ||
      newFiles.some((file) => file.size <= 0 || file.size > MAX_FILE_BYTES) ||
      [...retained.map((item) => item.file), ...newFiles].reduce(
        (sum, file) => sum + file.size,
        0,
      ) > MAX_TOTAL_BYTES
    ) {
      setError('בחר עד 6 קבצים להגשה, עד 3MB לקובץ ועד 8MB בסך הכול. קובץ ריק אינו נתמך.');
      return;
    }
    if (
      newFiles.some(
        (file) =>
          !artifactExtensions.includes(file.name.split('.').pop()?.toLowerCase() || '') ||
          /[\x00-\x1f\x7f/\\]/.test(file.name) ||
          file.name.length > 180,
      )
    ) {
      setError('בחר קובץ קוד או טקסט, PDF, PNG או JPEG.');
      return;
    }
    onChange([
      ...retained,
      ...newFiles.map((file) => ({ id: crypto.randomUUID(), criterionId, file })),
    ]);
    setError('');
  }
  return (
    <div className="artifact-picker">
      <div
        className={`artifact-dropzone ${dragging ? 'is-dragging' : ''}`}
        onDragOver={(event) => {
          event.preventDefault();
          if (!disabled) setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDragging(false);
          if (!disabled) add(Array.from(event.dataTransfer.files));
        }}
      >
        <FileUp aria-hidden="true" size={26} />
        <strong>קבצים שתומכים בתשובה שלך</strong>
        <p>גרור לכאן קוד, צילום מסך או PDF, או בחר קובץ מהמחשב.</p>
        <input
          ref={picker}
          type="file"
          className="sr-only"
          tabIndex={-1}
          aria-label={`קבצים לשאלה ${criterionId}`}
          accept={artifactAccept}
          multiple={!replaceId}
          disabled={disabled}
          onChange={(event) => {
            if (event.target.files) add(Array.from(event.target.files), replaceId);
            setReplaceId(undefined);
            event.target.value = '';
          }}
        />
        <button
          type="button"
          className="button secondary"
          disabled={disabled}
          onClick={() => {
            setReplaceId(undefined);
            picker.current?.click();
          }}
        >
          בחירת קבצים
        </button>
        <small>עד 3MB לקובץ · 6 קבצים ו־8MB להגשה · בלי סיסמאות או מידע של לקוחות</small>
      </div>
      <p role="status" className="form-error">
        {error}
      </p>
      <ul className="artifact-list" aria-label="קבצים שנבחרו לשאלה">
        {files
          .filter((item) => item.criterionId === criterionId)
          .map((item) => (
            <li key={item.id}>
              <div className="artifact-heading">
                <strong dir="auto">{item.file.name}</strong>
                <span dir="ltr">{(item.file.size / 1024).toFixed(1)} KB</span>
              </div>
              <FilePreview file={item.file} />
              <div className="artifact-actions">
                <button
                  type="button"
                  className="button subtle"
                  disabled={disabled}
                  aria-label={`החלפת ${item.file.name}`}
                  onClick={() => {
                    setReplaceId(item.id);
                    picker.current?.click();
                  }}
                >
                  <RefreshCw size={14} />
                  החלפה
                </button>
                <button
                  type="button"
                  className="button subtle"
                  disabled={disabled}
                  aria-label={`הסרת ${item.file.name}`}
                  onClick={() => onChange(files.filter((file) => file.id !== item.id))}
                >
                  <X size={14} />
                  הסרה
                </button>
              </div>
              <small className="muted">הקובץ יישמר בחשבון שלך רק בעת ההגשה.</small>
            </li>
          ))}
      </ul>
    </div>
  );
}

import Link from '@/components/workspace-navigation';
export function PortfolioCard({
  title,
  summary,
  lessonId,
  status,
  fileCount,
  preview = false,
}: {
  title: string;
  summary: string;
  lessonId?: string;
  status: string;
  fileCount: number;
  preview?: boolean;
}) {
  return (
    <article className="portfolio-card card">
      <p className="eyebrow">{preview ? 'כך העבודה תיראה בתיק שלך' : 'העבודה שלי'}</p>
      <h3 dir="auto">{title}</h3>
      <p className="reflection-text" dir="auto">
        {summary || 'עדיין לא נכתב תיאור לעבודה.'}
      </p>
      <div className="portfolio-meta">
        <span className="pill">{status}</span>
        <span>קבצים מצורפים: {fileCount}</span>
        <span>פרטי · רק לך ולבודק מורשה</span>
      </div>
      {lessonId && (
        <Link href={`/learn/${lessonId}#assessment`} className="text-link">
          לשיעור ולדרישות העבודה ←
        </Link>
      )}
    </article>
  );
}

'use client';
import { useState } from 'react';
import type { ArtifactMetadata } from '@/lib/domain/artifacts';
import type { AgentEvaluation } from '@/lib/agents/evaluate';

const errors: Record<string, string> = {
  AI_NOT_CONFIGURED:
    'המשוב באמצעות AI עדיין אינו זמין. אפשר להמשיך ללמוד ולהגיש עבודה לבדיקה אנושית.',
  MENTOR_BUSY: 'בקשה קודמת עדיין מתבצעת. המתן לסיומה.',
  MENTOR_DAILY_LIMIT: 'הגעת למגבלה היומית של בקשות AI. אפשר להמשיך ללמוד ללא המשוב האוטומטי.',
  AI_RATE_LIMIT: 'שירות ה־AI לא קיבל את הבקשה כרגע. לא בוצע ניסיון חוזר אוטומטי.',
  EVALUATION_CONTEXT_LIMIT: 'החומר שנבחר גדול מדי לבקשה אחת. נסה לבחור פחות קבצים.',
  AI_CONNECTION_FAILED: 'החיבור נקטע. רענן את העמוד כדי לבדוק אם נשמר משוב לפני שליחה נוספת.',
};
const criterionStatus = {
  supported: 'נמצאו ראיות בסעיף',
  'needs-work': 'כדאי לשפר את הסעיף',
  unclear: 'אין מספיק מידע למסקנה',
};
export function EvaluationPanel({
  submissionId,
  files,
  criteria,
  ready,
  initial,
}: {
  submissionId: string;
  files: ArtifactMetadata[];
  criteria: { id: string; prompt: string }[];
  ready: boolean;
  initial?: AgentEvaluation;
}) {
  const [selected, setSelected] = useState<string[]>([]),
    [consent, setConsent] = useState(false),
    [busy, setBusy] = useState(false),
    [status, setStatus] = useState(''),
    [evaluation, setEvaluation] = useState(initial);
  async function evaluate() {
    if (!consent || busy || !ready) return;
    setBusy(true);
    setStatus('מכין משוב על ההגשה…');
    try {
      const response = await fetch('/api/agents/evaluate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          requestId: crypto.randomUUID(),
          submissionId,
          artifactIds: selected,
          consent: true,
          explanationLevel: 'practical',
        }),
      });
      const result = await response.json();
      if (!response.ok) {
        setStatus(errors[result.error] || 'לא נשמר משוב חדש. לא בוצע ניסיון חוזר אוטומטי.');
        return;
      }
      setEvaluation(result.evaluation);
      setStatus('המשוב נשמר בחשבון שלך.');
    } catch {
      setStatus('החיבור נקטע. רענן את העמוד כדי לבדוק אם נשמר משוב לפני שליחה נוספת.');
    } finally {
      setBusy(false);
    }
  }
  return (
    <section className="settings-card" aria-label="משוב אוטומטי על ההגשה">
      <h3>משוב אוטומטי · לבחירתך</h3>
      <p>
        אפשר לבקש עזרה בזיהוי מה ברור בעבודה ומה כדאי לשפר. זהו משוב באמצעות AI לפי דרישות התרגיל.
        הוא עשוי לכלול טעויות ואינו אישור לשליטה בנושא.
      </p>
      {!ready && <p className="notice">המשוב באמצעות AI עדיין אינו זמין.</p>}
      {files.length > 0 && (
        <fieldset disabled={busy}>
          <legend>אילו קבצים לצרף למשוב?</legend>
          {files.map((file) => (
            <label className="toggle-row" key={file.id}>
              <input
                type="checkbox"
                checked={selected.includes(file.id)}
                onChange={(event) =>
                  setSelected((current) =>
                    event.target.checked
                      ? [...current, file.id]
                      : current.filter((id) => id !== file.id),
                  )
                }
              />
              <span dir="auto">{file.name}</span>
              <span className="tiny">{Math.ceil(file.size / 1024)} KB</span>
            </label>
          ))}
        </fieldset>
      )}
      <label className="toggle-row">
        <input
          type="checkbox"
          checked={consent}
          disabled={busy}
          onChange={(event) => setConsent(event.target.checked)}
        />
        אני מסכים לשליחת תוכן מהתשובות השמורות ומהקבצים שבחרתי ל־OpenAI לצורך המשוב.
      </label>
      <button
        className="button secondary"
        type="button"
        disabled={!ready || !consent || busy}
        onClick={evaluate}
      >
        {busy ? 'ממתינים למשוב…' : 'בקשת משוב אוטומטי'}
      </button>
      <p role="status">{status}</p>
      {evaluation && (
        <div className="evaluation-feedback">
          <h4>סיכום המשוב האוטומטי</h4>
          <p className="reflection-text">{evaluation.feedback.summary}</p>
          {evaluation.feedback.criteria.map((item) => (
            <section className="notice" key={item.criterionId}>
              <h4>
                {criteria.find((criterion) => criterion.id === item.criterionId)?.prompt ||
                  'סעיף מהמחוון המקורי'}
              </h4>
              <p>לפי המשוב: {criterionStatus[item.status]}</p>
              <p className="reflection-text">{item.feedback}</p>
              {item.evidence && (
                <p className="reflection-text">על מה המשוב מבוסס: {item.evidence}</p>
              )}
              <p className="reflection-text">הצעד הבא: {item.nextStep}</p>
            </section>
          ))}
          <details>
            <summary>איזה חומר נשלח למשוב?</summary>
            <p>
              הקוד לא הורץ. רק החלקים המפורטים כאן נשלחו למודל; המשוב אינו אימות טכני של העבודה.
            </p>
            <ul>
              {evaluation.coverage.evidence.map((item) => (
                <li key={item.criterionId}>
                  {criteria.find((criterion) => criterion.id === item.criterionId)?.prompt}: נשלחו{' '}
                  {item.charactersProvided} מתוך {item.totalCharacters} תווים.
                </li>
              ))}
              {evaluation.coverage.artifacts.map((item) => (
                <li key={item.id}>
                  <bdi>{item.name}</bdi>: {item.reason}
                  {typeof item.charactersProvided === 'number' &&
                    ` נשלחו ${item.charactersProvided} תווים.`}
                </li>
              ))}
            </ul>
          </details>
        </div>
      )}
    </section>
  );
}
